definition.script:
pipeline {
    agent any

    parameters {
        string(name: 'PROJECT_ID', defaultValue: 'nu1525', description: 'Nombre o ID del proyecto /n Ejemplo: nu1525')
        string(name: 'WEBLOGIC_TAG_VERSION', defaultValue: '12.2.1.4', description: 'Versión del tag del contenedor de WebLogic disponible: 12.2.1.4')
        string(name: 'WEBLOGIC_HOST_PORT', defaultValue: '7001', description: 'Puerto externo para WebLogic')
        string(name: 'WEBLOGIC_HOST_MONITOR', defaultValue: '9002', description: 'Puerto externo para NodeManager')
    }

    environment {
        DOCKER_IMAGE = "${params.WEBLOGIC_CONTAINER_NAME}:${params.WEBLOGIC_TAG_VERSION}"
        AZURE_REPO = "https://darias:FrEVryWWGJXSmIpurkWpflMLYIOvmUmpyiS6zcIrDUY4a3YlDMRQJQQJ99BDACAAAAAmugoDAAAGAZDO3Fy0@dev.azure.com/darias0313/Pruebas/_git/poc-corfi"
        DATA_RUTE_LOCAL = "/root/POC/jenkins-nexus/data/weblogic/"
        DATA_RUTE = "${env.DATA_RUTE_LOCAL}"+"weblogic-"+"${PROJECT_ID}"
    }

    stages {
        stage('Clonar repositorio') {
            steps {
                git url: "${env.AZURE_REPO}", branch: 'feature/test'
            }
        }

        stage('Crear Volumen y Permisos') {
            steps {
                 script {
                    sh """
                        pwd
                        ls -ltra
                        cd ${env.DATA_RUTE_LOCAL}
                        ls -ltra
                        mkdir -p weblogic-${PROJECT_ID}
                        sudo chown -R 1000:1000 weblogic-${PROJECT_ID}
                        sudo chmod 644 weblogic-${PROJECT_ID}
                    """
                }
            }
        }

        stage('Ejecutar Docker Compose') {
            steps {
                script {
                    sh """
                        cd weblogic
                        sed -i 's/{{PROJECT_ID}}/${PROJECT_ID}/g' docker-compose.yaml
                        sed -i 's/{{WEBLOGIC_TAG_VERSION}}/${WEBLOGIC_TAG_VERSION}/g' docker-compose.yaml
                        sed -i 's/{{WEBLOGIC_HOST_PORT}}/${WEBLOGIC_HOST_PORT}/g' docker-compose.yaml
                        sed -i 's/{{WEBLOGIC_HOST_MONITOR}}/${WEBLOGIC_HOST_MONITOR}/g' docker-compose.yaml
                        sed -i 's|{{DATA_RUTE}}|${DATA_RUTE}|g' docker-compose.yaml
                        export PATH=$PATH:$HOME/.local/bin && podman-compose --version
                        sudo chown 1000:1000 ./create_domain.py
                        sudo chmod 644 ./create_domain.py
                        podman-compose up -d
                    """
                }
            }
        }
    }
}
